"""Round-robin scheduler module."""


def _get_enabled_workers(workers: list[dict]) -> list[str]:
    """Return names of enabled workers."""
    return [w["name"] for w in workers if w.get("enabled", True)]


def _try_assign_job(
    job: str,
    enabled_workers: list[str],
    index: int,
    assigned_counts: dict[str, int],
    capacities: dict[str, int] | None,
) -> tuple[dict | None, int]:
    """Try to assign a job to the next available worker.

    Returns a tuple of (assignment_dict_or_None, new_index).
    """
    num_workers = len(enabled_workers)
    for offset in range(num_workers):
        worker_name = enabled_workers[(index + offset) % num_workers]
        cap = capacities.get(worker_name) if capacities is not None else None
        if cap is None or assigned_counts[worker_name] < cap:
            assignment = {"job": job, "worker": worker_name}
            new_index = (index + offset + 1) % num_workers
            return assignment, new_index
    return None, index


def assign_round_robin(
    workers: list[dict],
    jobs: list[str],
    capacities: dict[str, int] | None = None,
) -> list[dict]:
    """Assign jobs to enabled workers in round-robin order.

    Args:
        workers: List of worker dicts with "name" and optional "enabled" fields.
        jobs: List of job strings to assign.
        capacities: Optional mapping of worker name to maximum number of jobs
            that worker may receive. Workers absent from the mapping have no
            cap. Jobs that cannot be assigned due to capacity limits are
            omitted from the result.

    Returns:
        List of dicts shaped as {"job": str, "worker": str}.

    Raises:
        TypeError: If arguments are of incorrect types.
        ValueError: If there are no enabled workers, or if worker dicts are
            malformed, or if capacity values are not positive integers.
    """
    # --- Input validation ---
    if not isinstance(workers, list):
        raise TypeError(
            f"'workers' must be a list, got {type(workers).__name__!r}."
        )
    if not isinstance(jobs, list):
        raise TypeError(
            f"'jobs' must be a list, got {type(jobs).__name__!r}."
        )
    if capacities is not None and not isinstance(capacities, dict):
        raise TypeError(
            f"'capacities' must be a dict or None, got {type(capacities).__name__!r}."
        )

    for i, worker in enumerate(workers):
        if not isinstance(worker, dict):
            raise TypeError(
                f"Each worker must be a dict; workers[{i}] is {type(worker).__name__!r}."
            )
        if "name" not in worker:
            raise ValueError(
                f"Worker at index {i} is missing the required 'name' field."
            )
        if not isinstance(worker["name"], str):
            raise ValueError(
                f"Worker 'name' at index {i} must be a str, "
                f"got {type(worker['name']).__name__!r}."
            )
        if worker["name"] == "":
            raise ValueError(
                f"Worker 'name' at index {i} must not be an empty string."
            )
        enabled = worker.get("enabled", True)
        if not isinstance(enabled, bool):
            raise TypeError(
                f"Worker 'enabled' field at index {i} must be a bool, "
                f"got {type(enabled).__name__!r}."
            )

    for i, job in enumerate(jobs):
        if not isinstance(job, str):
            raise TypeError(
                f"Each job must be a str; jobs[{i}] is {type(job).__name__!r}."
            )

    if capacities is not None:
        for key, value in capacities.items():
            if not isinstance(key, str):
                raise TypeError(
                    f"All keys in 'capacities' must be str, got {type(key).__name__!r}."
                )
            if not isinstance(value, int) or isinstance(value, bool):
                raise TypeError(
                    f"Capacity for worker {key!r} must be an int, "
                    f"got {type(value).__name__!r}."
                )
            if value < 0:
                raise ValueError(
                    f"Capacity for worker {key!r} must be non-negative, got {value}."
                )

    # --- Core algorithm (unchanged) ---
    enabled_workers = _get_enabled_workers(workers)

    if not enabled_workers:
        raise ValueError("No enabled workers available.")

    result = []
    assigned_counts: dict[str, int] = {name: 0 for name in enabled_workers}
    index = 0

    for job in jobs:
        assignment, index = _try_assign_job(
            job, enabled_workers, index, assigned_counts, capacities
        )
        if assignment is not None:
            assigned_counts[assignment["worker"]] += 1
            result.append(assignment)

    return result

